CREATE TABLE public.order_refund_requests(id uuid PRIMARY KEY,inquiry_id uuid NOT NULL REFERENCES public.rental_inquiries(id),deposit_cents integer NOT NULL DEFAULT 0 CHECK(deposit_cents>=0),rent_cents integer NOT NULL DEFAULT 0 CHECK(rent_cents>=0),status text NOT NULL DEFAULT 'creating' CHECK(status IN ('creating','pending','succeeded','failed','partial_failed','canceled')),payout_method text NOT NULL CHECK(payout_method IN ('stripe','transfer','cash')),allocations jsonb NOT NULL DEFAULT '[]',created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,bank_reference text,CHECK(deposit_cents+rent_cents>0));
GRANT SELECT ON public.order_refund_requests TO authenticated; GRANT ALL ON public.order_refund_requests TO service_role; ALTER TABLE public.order_refund_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY branch_read ON public.order_refund_requests FOR SELECT TO authenticated USING(public.can_edit_operations(auth.uid()) AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.staff_profiles s JOIN public.rental_inquiries i ON i.id=inquiry_id WHERE s.user_id=auth.uid() AND s.is_active AND public.slt_stock_location(s.location)=public.slt_stock_location(i.location))));
CREATE INDEX order_refund_requests_inquiry ON public.order_refund_requests(inquiry_id);
CREATE UNIQUE INDEX order_refund_one_unresolved ON public.order_refund_requests(inquiry_id) WHERE status IN ('creating','pending','partial_failed');
CREATE OR REPLACE FUNCTION public.order_refund_totals(_inquiry uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE i public.rental_inquiries; s public.deposit_settlements; b public.rental_refund_bases; invoice record; paid bigint; held bigint; rent_due bigint:=0; deposit_due bigint; d_used bigint:=0; r_used bigint:=0; pending boolean:=false; reason text; invoices integer;
BEGIN
SELECT * INTO i FROM public.rental_inquiries WHERE id=_inquiry; IF i.id IS NULL THEN RAISE EXCEPTION 'Auftrag nicht gefunden'; END IF;
IF auth.role() IS DISTINCT FROM 'service_role' AND NOT(public.can_edit_operations(auth.uid()) AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.staff_profiles sp WHERE sp.user_id=auth.uid() AND sp.is_active AND public.slt_stock_location(sp.location)=public.slt_stock_location(i.location)))) THEN RAISE EXCEPTION 'Keine Standortberechtigung' USING ERRCODE='42501'; END IF;
SELECT coalesce(sum(round((p->>'amount')::numeric*100)),0) INTO paid FROM jsonb_array_elements(coalesce(i.payments,'[]')) p;
held:=least(greatest(0,paid-round(coalesce((i.offer_payload->'totals'->>'grossAmount')::numeric,i.offer_total_gross,0)*100)),greatest(0,round(coalesce((i.offer_payload->>'deposit')::numeric,0)*100)));
SELECT * INTO s FROM public.deposit_settlements WHERE rental_inquiry_id=i.id; SELECT * INTO b FROM public.rental_refund_bases WHERE inquiry_id=i.id;
SELECT count(*) INTO invoices FROM public.inquiry_invoices WHERE rental_inquiry_id=i.id AND status NOT IN ('draft','cancelled');
IF s.id IS NOT NULL THEN deposit_due:=greatest(0,round(s.balance*100)); ELSE deposit_due:=held; IF i.cancelled_at IS NULL THEN reason:='Kaution zuerst abrechnen'; END IF; END IF;
IF b.id IS NOT NULL THEN rent_due:=greatest(0,round((b.paid_amount-b.gross_amount)*100));
ELSIF i.cancelled_at IS NOT NULL AND invoices=0 THEN rent_due:=greatest(0,paid-held-round((i.cancellation_payload->'totals'->>'grossAmount')::numeric*100));
ELSIF invoices=1 THEN SELECT * INTO invoice FROM public.inquiry_invoices WHERE rental_inquiry_id=i.id AND status NOT IN ('draft','cancelled'); IF invoice.invoice_kind IN ('invoice','final') AND invoice.parent_invoice_id IS NULL AND coalesce(jsonb_array_length(invoice.deducted_installments),0)=0 THEN rent_due:=greatest(0,round((invoice.paid_amount-invoice.gross_amount)*100)); ELSE reason:='Vorhandene Belege erfordern Korrekturabrechnung'; END IF;
ELSIF invoices>1 THEN reason:='Vorhandene Rechnungen und Abschläge erfordern Korrekturabrechnung'; END IF;
SELECT coalesce(sum(d.amount_cents) FILTER(WHERE d.status NOT IN ('failed','canceled')),0),coalesce(bool_or(d.status IN ('creating','pending','requires_action')),false) INTO d_used,pending FROM public.deposit_refunds d JOIN public.offer_payment_links l ON l.id=d.link_id WHERE l.inquiry_id=i.id AND l.inquiry_table='rental_inquiries';
IF s.payout_status='paid' AND s.payout_method IN ('cash','transfer') THEN d_used:=greatest(d_used,deposit_due); END IF;
SELECT coalesce(sum(r.amount_cents) FILTER(WHERE r.status NOT IN ('failed','canceled')),0),pending OR coalesce(bool_or(r.status IN ('creating','pending','requires_action','partial_failed')),false) INTO r_used,pending FROM public.rental_order_refunds r JOIN public.rental_refund_bases rb ON rb.id=r.basis_id WHERE rb.inquiry_id=i.id;
SELECT r_used+coalesce(sum(r.amount_cents) FILTER(WHERE r.status NOT IN ('failed','canceled')),0),pending OR coalesce(bool_or(r.status IN ('creating','pending','requires_action','partial_failed')),false) INTO r_used,pending FROM public.credit_note_refunds r JOIN public.inquiry_invoices inv ON inv.id=r.credit_note_id WHERE inv.rental_inquiry_id=i.id;
SELECT d_used+coalesce(sum(r.deposit_cents) FILTER(WHERE r.status NOT IN ('failed','canceled')),0),r_used+coalesce(sum(r.rent_cents) FILTER(WHERE r.status NOT IN ('failed','canceled')),0),pending OR coalesce(bool_or(r.status IN ('creating','pending','partial_failed')),false) INTO d_used,r_used,pending FROM public.order_refund_requests r WHERE r.inquiry_id=i.id;
RETURN jsonb_build_object('paid_cents',paid,'deposit_entitlement',deposit_due,'rent_entitlement',rent_due,'deposit_used',d_used,'rent_used',r_used,'deposit_available',greatest(0,deposit_due-d_used),'rent_available',greatest(0,rent_due-r_used),'pending',pending,'blocked_reason',reason,'basis_id',b.id);
END $$;
REVOKE ALL ON FUNCTION public.order_refund_totals(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.order_refund_totals(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.reserve_order_refund(_id uuid,_inquiry uuid,_actor uuid,_deposit integer,_rent integer,_method text,_allocations jsonb) RETURNS public.order_refund_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path=public SET lock_timeout='2s' AS $$
DECLARE totals jsonb; r public.order_refund_requests; i public.rental_inquiries; a jsonb;
BEGIN
IF auth.role() IS DISTINCT FROM 'service_role' OR NOT public.can_edit_operations(_actor) THEN RAISE EXCEPTION 'Nicht berechtigt' USING ERRCODE='42501'; END IF;
SELECT * INTO i FROM public.rental_inquiries WHERE id=_inquiry FOR UPDATE;
IF NOT public.has_role(_actor,'admin') AND NOT EXISTS(SELECT 1 FROM public.staff_profiles s WHERE s.user_id=_actor AND s.is_active AND public.slt_stock_location(s.location)=public.slt_stock_location(i.location)) THEN RAISE EXCEPTION 'Keine Standortberechtigung' USING ERRCODE='42501'; END IF;
IF _rent>0 AND NOT(public.has_role(_actor,'admin') OR public.has_role(_actor,'niederlassungsleiter')) THEN RAISE EXCEPTION 'Keine Berechtigung für Mieterstattungen' USING ERRCODE='42501'; END IF;
SELECT * INTO r FROM public.order_refund_requests WHERE id=_id; IF r.id IS NOT NULL THEN IF r.inquiry_id<>_inquiry OR r.deposit_cents<>_deposit OR r.rent_cents<>_rent THEN RAISE EXCEPTION 'Erstattungsauftrag unveränderlich'; END IF; RETURN r; END IF;
totals:=public.order_refund_totals(_inquiry); IF (totals->>'pending')::boolean THEN RAISE EXCEPTION 'Erstattung bereits in Bearbeitung; Status prüfen' USING ERRCODE='PT409'; END IF;
IF totals->>'blocked_reason' IS NOT NULL THEN RAISE EXCEPTION '%',totals->>'blocked_reason'; END IF;
IF _deposit<0 OR _rent<0 OR _deposit+_rent<=0 OR _deposit>(totals->>'deposit_available')::bigint OR _rent>(totals->>'rent_available')::bigint THEN RAISE EXCEPTION 'Betrag übersteigt verbleibenden Kautions- oder Mietanspruch' USING ERRCODE='23514'; END IF;
IF _method='stripe' THEN
IF jsonb_array_length(_allocations)=0 OR (SELECT sum((x->>'deposit_cents')::integer) FROM jsonb_array_elements(_allocations)x)<>_deposit OR (SELECT sum((x->>'rent_cents')::integer) FROM jsonb_array_elements(_allocations)x)<>_rent THEN RAISE EXCEPTION 'Ungültige Aufteilung'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(_allocations) ORDER BY value->>'payment_intent' LOOP
IF (a->>'amount_cents')::integer<>(a->>'deposit_cents')::integer+(a->>'rent_cents')::integer OR NOT EXISTS(SELECT 1 FROM public.offer_payment_links l WHERE l.inquiry_id=_inquiry AND l.status='paid' AND l.payment_intent_id=a->>'payment_intent') THEN RAISE EXCEPTION 'Ungültige Originalzahlung'; END IF;
PERFORM public.assert_stripe_refund_execution_capacity(a->>'payment_intent'); END LOOP;
ELSE
IF EXISTS(SELECT 1 FROM public.offer_payment_links WHERE inquiry_id=_inquiry AND status='paid') OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(i.payments,'[]')) p WHERE (_method='transfer' AND coalesce(p->>'label','')!~*'(überweisung|ueberweisung|bank)') OR (_method='cash' AND coalesce(p->>'label','')!~*'^bar') OR coalesce(p->>'reference','')~'^(pi_|cs_)') THEN RAISE EXCEPTION 'Rückzahlung nur auf ursprüngliche Zahlungsart'; END IF; END IF;
INSERT INTO public.order_refund_requests(id,inquiry_id,deposit_cents,rent_cents,payout_method,allocations,created_by) VALUES(_id,_inquiry,_deposit,_rent,_method,_allocations,_actor) RETURNING * INTO r; RETURN r;
END $$;
REVOKE ALL ON FUNCTION public.reserve_order_refund(uuid,uuid,uuid,integer,integer,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_order_refund(uuid,uuid,uuid,integer,integer,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.sync_order_refund(_id uuid,_intent text,_refund text,_status text,_amount integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r public.order_refund_requests; items jsonb; a jsonb;
BEGIN
IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Nicht berechtigt'; END IF; SELECT * INTO r FROM public.order_refund_requests WHERE id=_id FOR UPDATE;
SELECT value INTO a FROM jsonb_array_elements(r.allocations) WHERE value->>'payment_intent'=_intent;
IF a IS NULL OR (a->>'amount_cents')::integer<>_amount OR (a->>'refund_id' IS NOT NULL AND a->>'refund_id'<>_refund) OR NOT EXISTS(SELECT 1 FROM public.stripe_refund_receipts WHERE refund_id=_refund AND payment_intent=_intent AND amount_cents=_amount AND status=_status) THEN RAISE EXCEPTION 'Unpassender Providerbeleg'; END IF;
IF a->>'status' IN ('succeeded','failed','canceled') AND a->>'status'<>_status THEN RETURN; END IF;
SELECT jsonb_agg(CASE WHEN value->>'payment_intent'=_intent THEN value||jsonb_build_object('refund_id',_refund,'status',_status) ELSE value END) INTO items FROM jsonb_array_elements(r.allocations);
UPDATE public.order_refund_requests SET allocations=items,status=CASE WHEN (SELECT bool_and(value->>'status'='succeeded') FROM jsonb_array_elements(items)) THEN 'succeeded' WHEN (SELECT bool_or(value->>'status' IN ('failed','canceled')) FROM jsonb_array_elements(items)) THEN 'partial_failed' ELSE 'pending' END,completed_at=CASE WHEN (SELECT bool_and(value->>'status'='succeeded') FROM jsonb_array_elements(items)) THEN coalesce(completed_at,now()) ELSE completed_at END WHERE id=r.id; END $$;
REVOKE ALL ON FUNCTION public.sync_order_refund(uuid,text,text,text,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.sync_order_refund(uuid,text,text,text,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.guard_order_refund_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' OR (to_jsonb(NEW)-'status'-'allocations'-'completed_at'-'bank_reference') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'allocations'-'completed_at'-'bank_reference') OR (OLD.status='succeeded' AND NEW.status<>'succeeded') OR (OLD.bank_reference IS NOT NULL AND OLD.bank_reference IS DISTINCT FROM NEW.bank_reference) THEN RAISE EXCEPTION 'Erstattungsnachweis unveränderlich'; END IF; RETURN NEW; END $$;
CREATE TRIGGER order_refund_immutable BEFORE UPDATE OR DELETE ON public.order_refund_requests FOR EACH ROW EXECUTE FUNCTION public.guard_order_refund_immutable();
CREATE OR REPLACE FUNCTION public.guard_legacy_refund_after_combined() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; BEGIN IF TG_OP='UPDATE' THEN RETURN NEW; END IF; IF TG_TABLE_NAME='deposit_refunds' THEN SELECT inquiry_id INTO owner FROM public.offer_payment_links WHERE id=NEW.link_id; ELSIF TG_TABLE_NAME='rental_order_refunds' THEN SELECT inquiry_id INTO owner FROM public.rental_refund_bases WHERE id=NEW.basis_id; ELSE SELECT rental_inquiry_id INTO owner FROM public.inquiry_invoices WHERE id=NEW.credit_note_id; END IF; PERFORM 1 FROM public.rental_inquiries WHERE id=owner FOR UPDATE; IF EXISTS(SELECT 1 FROM public.order_refund_requests WHERE inquiry_id=owner AND status NOT IN ('failed','canceled')) THEN RAISE EXCEPTION 'Gemeinsame Erstattung bereits beauftragt; verbleibenden Anspruch dort prüfen' USING ERRCODE='PT409'; END IF; RETURN NEW; END $$;
CREATE TRIGGER aaaa_combined_refund_guard BEFORE INSERT ON public.deposit_refunds FOR EACH ROW EXECUTE FUNCTION public.guard_legacy_refund_after_combined(); CREATE TRIGGER aaaa_combined_refund_guard BEFORE INSERT ON public.rental_order_refunds FOR EACH ROW EXECUTE FUNCTION public.guard_legacy_refund_after_combined(); CREATE TRIGGER aaaa_combined_refund_guard BEFORE INSERT ON public.credit_note_refunds FOR EACH ROW EXECUTE FUNCTION public.guard_legacy_refund_after_combined();